func respondFixed(c *gin.Context, status int, code string) {
	c.Data(status, "text/plain; charset=utf-8", []byte("error="+code))
}

func respondInvalidInput(c *gin.Context) {
	respondFixed(c, http.StatusBadRequest, codeInvalidInput)
}

